long long sumAndFreeDynamicMatrix(int rows, int cols, int initValue) {
    int** mat = new int*[rows];
    for (int i = 0; i < rows; ++i) {
        mat[i] = new int[cols];
        for (int j = 0; j < cols; ++j) {
            mat[i][j] = initValue;
        }
    }
    long long total = 0;
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            total += mat[i][j];
        }
        delete[] mat[i];
    }
    delete[] mat;
    return total;
}

