class SimpleVector {
private:
    int* m_data;
    size_t m_size;
    size_t m_capacity;

    void resize() {
        m_capacity = (m_capacity == 0) ? 2 : m_capacity * 2;
        int* newData = new int[m_capacity];
        for (size_t i = 0; i < m_size; ++i) newData[i] = m_data[i];
        delete[] m_data;
        m_data = newData;
    }
public:
    SimpleVector() : m_data(new int[2]), m_size(0), m_capacity(2) {}
    ~SimpleVector() { delete[] m_data; }
    void push_back(int val) {
        if (m_size >= m_capacity) resize();
        m_data[m_size++] = val;
    }
    size_t size() const { return m_size; }
    size_t capacity() const { return m_capacity; }
    int get(size_t index) const {
        if (index >= m_size) throw std::out_of_range("Index out of range");
        return m_data[index];
    }
};

