class Polynomial:
    def __init__(self, *coeffs):
        self.coeffs = list(coeffs)
    def __repr__(self):
        return f"Polynomial({', '.join(map(str, self.coeffs))})"
    def __call__(self, x):
        res = 0
        deg = len(self.coeffs) - 1
        for i, c in enumerate(self.coeffs):
            res += c * (x ** (deg - i))
        return res
    def __add__(self, other):
        c1 = list(self.coeffs)
        c2 = list(other.coeffs)
        max_len = max(len(c1), len(c2))
        c1 = [0] * (max_len - len(c1)) + c1
        c2 = [0] * (max_len - len(c2)) + c2
        sum_coeffs = [a + b for a, b in zip(c1, c2)]
        return Polynomial(*sum_coeffs)
